"""Pre-enrolled offline recovery, registered email and a new real WebAuthn key."""
import importlib.util,unittest,json
from pathlib import Path
from playwright.sync_api import expect
spec=importlib.util.spec_from_file_location('keys_qa',Path(__file__).with_name('test-key-management.py'));qa=importlib.util.module_from_spec(spec);spec.loader.exec_module(qa)
ROOT,ORIGIN=qa.ROOT,qa.ORIGIN
class Emergency(qa.Keys):
    def prepare_codes(self,lost=False):
        self.keys();self.local('/test/enable-emergency',{});self.page.reload();expect(self.page.locator('#generate-codes')).to_be_visible();self.page.locator('#generate-codes').click();self.page.locator('#codes-confirm').click();expect(self.page.locator('#prove')).to_be_visible();self.lose_key='prove' if lost else None;self.page.locator('#prove').click()
        if lost:expect(self.page.locator('#retry')).to_be_enabled();self.page.locator('#retry').click()
        expect(self.page.locator('#code-list li')).to_have_count(6);self.assertTrue(self.page.evaluate('document.documentElement.scrollWidth<=innerWidth'));return self.page.locator('#code-list li').all_text_contents()
    def email_recovery(self):
        self.page.goto(ORIGIN+'/acesso-dev.html#recuperar-pin');expect(self.page.locator('#recovery-form')).to_be_visible();self.page.locator('#recovery-email').fill('owner@example.invalid');self.page.get_by_role('button',name='Enviar código de recuperação').click();expect(self.page.locator('#email-form')).to_be_visible();self.page.locator('#email-code').fill(self.local('/test/code')['code']);self.page.get_by_role('button',name='Confirmar código',exact=True).click();expect(self.page.locator('#pin-form')).to_be_visible()
    def reserve(self,code):
        self.page.locator('#use-rescue').check();self.page.locator('#rescue-code').fill(code);self.page.locator('#rescue-confirm').click();expect(self.page.locator('#rescue-status')).to_contain_text('Código confirmado');expect(self.page.locator('#rescue-code')).to_have_value('')
    def pin(self):
        self.page.locator('#new-pin').fill('9382');self.page.locator('#confirm-pin').fill('9382');self.page.get_by_role('button',name='Salvar PIN e continuar',exact=True).click();expect(self.page.locator('#passkey')).to_be_visible()
    def test_emergency_mobile_download_then_recover_without_old_authenticator_and_login_new_key(self):
        codes=self.prepare_codes()
        with self.page.expect_download() as d:self.page.locator('#download-codes').click()
        text=d.value.path().read_text();self.assertTrue(all(c in text for c in codes));self.assertNotIn('owner@example.invalid',text);self.second_authenticator();self.email_recovery();self.reserve(codes[0]);self.pin();self.page.locator('#passkey-button').click();expect(self.page.locator('#complete')).to_be_visible();self.assertEqual(self.local('/test/emergency-state'),{'issued':1,'recovered':1,'remaining':0});self.assertEqual(self.local('/test/keys-state')['active'],1);self.assert_no_secrets_in_browser_storage();self.logout();self.begin_login(pin='9382');expect(self.page.locator('#passkey')).to_be_visible();self.page.locator('#passkey-button').click();expect(self.page.locator('#complete')).to_be_visible();self.page.goto(ORIGIN+'/minhas-chaves-dev.html');expect(self.page.locator('#codes-status')).to_contain_text('não tem uma lista válida');self.assertTrue(self.page.evaluate('document.documentElement.scrollWidth<=innerWidth'));folder=ROOT/'work/qa-emergency';folder.mkdir(parents=True,exist_ok=True);self.page.screenshot(path=str(folder/'recuperacao-celular.png'),full_page=True);self.assertEqual(self.errors,[])
    def test_emergency_lost_kit_ack_returns_same_codes_and_reload_does_not_auto_disclose(self):
        codes=self.prepare_codes(lost=True);self.assertEqual(self.local('/test/emergency-state')['issued'],1);self.assertEqual(self.key_commands[-1],self.key_commands[-2]);self.page.locator('#reload').click();expect(self.page.locator('#code-list li')).to_have_count(0);self.page.reload();expect(self.page.locator('#code-list li')).to_have_count(0);expect(self.page.locator('#prove')).to_have_text('Conferir códigos deste fluxo');self.page.locator('#prove').click();expect(self.page.locator('#code-list li')).to_have_count(6);self.assertEqual(self.page.locator('#code-list li').all_text_contents(),codes);self.page.locator('#hide-codes').click();expect(self.page.locator('#code-list li')).to_have_count(0);self.assertEqual(self.page.evaluate('Object.keys(sessionStorage)'),[]);self.assertEqual(self.errors,[])
    def test_emergency_codes_expire_from_dom_without_persistent_storage(self):
        self.page.clock.install();self.prepare_codes();self.page.clock.fast_forward(301000);expect(self.page.locator('#code-list li')).to_have_count(0);expect(self.page.locator('#code-board')).to_be_hidden();expect(self.page.locator('#status')).to_contain_text('prazo de exibição terminou');self.assertEqual(self.page.evaluate('Object.keys(localStorage)'),[]);self.assertEqual(self.page.evaluate('Object.keys(sessionStorage)'),[]);self.assertEqual(self.errors,[])
    def test_emergency_wrong_code_does_not_create_key_or_allow_continuation(self):
        self.prepare_codes();self.email_recovery();self.page.locator('#use-rescue').check();self.page.locator('#rescue-code').fill('0000-0000-0000-0000-0000-0000-0000-0000');self.page.locator('#rescue-confirm').click();expect(self.page.locator('#status')).to_contain_text('Não foi possível confirmar');self.page.locator('#new-pin').fill('9382');self.page.locator('#confirm-pin').fill('9382');self.page.get_by_role('button',name='Salvar PIN e continuar',exact=True).click();expect(self.page.locator('#status')).to_contain_text('Valide o código');expect(self.page.locator('#passkey')).to_be_hidden();self.assertEqual(self.local('/test/emergency-state'),{'issued':1,'recovered':0,'remaining':6});self.assertEqual(self.errors,[])
    def test_emergency_new_batch_invalidates_old_and_visibility_change_does_not_store_codes(self):
        old=self.prepare_codes();self.page.locator('#generate-codes').click();self.page.locator('#codes-confirm').click();self.page.locator('#prove').click();expect(self.page.locator('#code-list li')).to_have_count(6);new=self.page.locator('#code-list li').all_text_contents();self.assertNotEqual(old,new);self.email_recovery();self.page.locator('#use-rescue').check();self.page.locator('#rescue-code').fill(old[0]);self.page.locator('#rescue-confirm').click();expect(self.page.locator('#status')).to_contain_text('Não foi possível confirmar');self.reserve(new[0]);self.assertEqual(self.local('/test/emergency-state')['remaining'],5);self.assert_no_secrets_in_browser_storage();self.assertEqual(self.errors,[])
if __name__=='__main__':
    suite=unittest.TestSuite(Emergency(name) for name in unittest.defaultTestLoader.getTestCaseNames(Emergency) if name.startswith('test_emergency_'));r=unittest.TextTestRunner(verbosity=2).run(suite);raise SystemExit(0 if r.wasSuccessful() else 1)
